    /// Kind is "turn.status".
    public let kind: MessageKind
    /// State is the gateway work in progress; idle ends the turn, including
    /// one that produced no speech.
    public let state: TurnState

    public init(kind: MessageKind, state: TurnState) {
        self.kind = kind
        self.state = state
    }
}

